public void run(METCancelSalesOrderTaskContract _contract)
{
    METCancelSalesOrderStaging staging;

    while select forupdate staging
        where staging.ExecutionId == _contract.parmExecutionId()
        && staging.PartitionId == _contract.parmTask()
        && staging.Status == METCancelSalesOrderStatus::Pending
    {
        this.cancelorder(staging);
    }
}

private void cancelorder(METCancelSalesOrderStaging _staging)
{
    SalesLine  salesline;
    METCancelSalesOrderStaging stagingupd;

    try
    {
        if(_staging)
        {
            ttsbegin;
            select forupdate stagingupd
                where stagingupd.RecId == _staging.RecId;

            if(stagingupd)
            {
                stagingupd.status = METCancelSalesOrderStatus::Executing;
                stagingupd.update();
            }
            ttscommit;

            Info(strFmt("Cancelling sales id %1", _staging.SalesId));
            ttsbegin;
            while select forupdate salesline
                where salesline.SalesId == _staging.SalesId
            {
                if(salesline.RemainInventPhysical != 0)
                {
                    salesline.skipDataMethods(true);
                    salesline.skipBusinessEvents(true);
                    salesline.skipEvents(true);
                    salesline.RemainSalesPhysical = 0;
                    salesline.RemainInventPhysical = 0;
                    if(salesline.inventTable().pdsCWItem())
                    {
                        salesline.PdsCWRemainInventPhysical = 0;
                    }
                    salesline.update();
                }
            }
            ttscommit;

            ttsbegin;
            select forupdate stagingupd 
                where stagingupd.RecId == _staging.RecId;

            if(stagingupd)
            {
                stagingupd.Status = METCancelSalesOrderStatus::Completed;
                stagingupd.update();
            }

            ttscommit;

        }
    }

    catch (Exception::Error)
    {
        ttsabort;

        ttsbegin;
        _staging.Status = METCancelSalesOrderStatus::Failed;
        _staging.update();
        ttscommit;
    }

    catch(Exception::UpdateConflict)
    {
        if(appl.ttsLevel() == 0)
        {
            if(xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            retry;
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
